        // Write back to storage
        vm.store(TARGET, bytes32(0), newSlot0);

        // Verify the change
        (, , , , , , uint256 buyTaxAfter, , ) = ICartoondoge(TARGET).getTaxes();
        console.log("After exploit: buyTax = %s", buyTaxAfter);

        // Assert that buyTax > 20
